class SpecialMeter
{
public:
    bool CanFaceLink() const;
    bool CanRegionLink() const;
    void Decrease(float amount);
};

class BoardController
{
    char padding[0x460];
    int inAir;

public:
    bool InAir() const { return inAir; }
};

class kellyslater_controller
{
    char padding0[0xFC];
    int trickRegion;
    char padding1[0x15B8];
    int doingTrick2;
    char padding2[0x258];
    int doingTrick1;
    char padding3[0x1F8];
    int joystick;

public:
    int GetTrickRegion() const { return trickRegion; }
    int get_joystick_num() const { return joystick; }
    bool IsDoingTrick() const { return doingTrick1 || doingTrick2; }
    BoardController &get_board_controller() { return *(BoardController *) this; }
};

class input_mgr
{
public:
    static input_mgr *instance;
    static input_mgr *inst() { return instance; }
    float get_control_state(int device, int control) const;
};

class ScoringManager
{
public:
    class Chain
    {
    public:
        bool IsInteresting() const;
    };

private:
    char base[8];
    kellyslater_controller *ksctrl;
    int playerIdx;
    SpecialMeter *specialMeter;
    char padding0[0x198];
    Chain chain;
    char padding1[0x1F];
    int prevTrickRegion;
    char padding2[8];
    int specialTrick;

public:
    void Update(float dt);
    void FinishChain(bool successful);
};

