__asm__(".equ CanRegionLink__C12SpecialMeter, 0x002510F0");
__asm__(".equ Decrease__12SpecialMeterf, 0x00250FF0");
__asm__(".equ IsInteresting__CQ214ScoringManager5Chain, 0x002494E8");
__asm__(".equ FinishChain__14ScoringManagerb, 0x00248758");

void ScoringManager::Update(const float dt)
{
    bool finishChain = false;

    if (specialTrick == 1 || specialTrick == 2)
        specialTrick = 0;

    if (ksctrl->GetTrickRegion() == 0)
    {
        if (!specialMeter->CanFaceLink() && !specialMeter->CanRegionLink() &&
            chain.IsInteresting())
            finishChain = true;
    }

    if (input_mgr::inst()->get_control_state(ksctrl->get_joystick_num(), 193) == 1.0f &&
        !ksctrl->IsDoingTrick() && !ksctrl->get_board_controller().InAir() &&
        specialMeter->CanRegionLink())
    {
        finishChain = true;
        specialMeter->Decrease(1.0f);
    }

    if (finishChain)
        FinishChain(true);

    prevTrickRegion = ksctrl->GetTrickRegion();
}
